"""Ask for JSON matching a schema, parse it, validate it with stdlib checks, retry if invalid."""
import json
import os

import requests

BASE_URL = os.environ.get("LOCAL_MODEL_URL") or os.environ.get("BASE_URL", "http://localhost:11434/v1")
MODEL = os.environ.get("LOCAL_MODEL") or os.environ.get("MODEL", "qwen2.5:1.5b")
SCHEMA = {
    "type": "object",
    "properties": {"name": {"type": "string"}, "age": {"type": "integer"}, "city": {"type": "string"}},
    "required": ["name", "age", "city"],
    "additionalProperties": False,
}


def chat(messages, response_format=None, base_url=BASE_URL, model=MODEL):
    payload = {"model": model, "messages": messages, "temperature": 0}
    if response_format:
        payload["response_format"] = response_format  # constrained decoding on the server, where supported
    resp = requests.post(f"{base_url}/chat/completions", json=payload, timeout=120)
    resp.raise_for_status()
    return resp.json()["choices"][0]["message"]["content"]


def validate(obj):
    """Return a list of problems (empty list = valid). Plain code, no model involved."""
    # trust boundary: model JSON is untrusted input until this returns []
    if not isinstance(obj, dict):
        return ["top level must be an object"]
    errors = [f"missing key {k!r}" for k in SCHEMA["required"] if k not in obj]
    errors += [f"unexpected key {k!r}" for k in obj if k not in SCHEMA["properties"]]
    if "name" in obj and not isinstance(obj["name"], str):
        errors.append("name must be a string")
    if "city" in obj and not isinstance(obj["city"], str):
        errors.append("city must be a string")
    if "age" in obj and (type(obj["age"]) is not int or not 0 <= obj["age"] <= 150):
        errors.append("age must be an integer 0-150")
    return errors


def extract_person(text, use_response_format=False, max_attempts=3, **kw):
    messages = [
        {"role": "system", "content": "Extract the person from the text inside <input> tags. Reply with "
                                      "ONLY a JSON object matching this JSON schema:\n" + json.dumps(SCHEMA)},
        {"role": "user", "content": f"<input>{text}</input>"},
    ]
    rf = {"type": "json_schema", "json_schema": {"name": "person", "schema": SCHEMA, "strict": True}}
    for attempt in range(1, max_attempts + 1):
        reply = chat(messages, rf if use_response_format else None, **kw)
        try:
            obj = json.loads(reply)  # strict parse: prose or code fences fail here
            errors = validate(obj)
        except json.JSONDecodeError as exc:
            errors = [f"not valid JSON ({exc.msg})"]
        print(f"  attempt {attempt}: {'OK' if not errors else errors}")
        if not errors:
            return obj, attempt
        # bounded retry: feed the bad answer and the exact problem back, then ask again
        messages += [{"role": "assistant", "content": reply},
                     {"role": "user", "content": f"Invalid: {'; '.join(errors)}. Reply with ONLY the JSON object."}]
    raise ValueError(f"no valid JSON after {max_attempts} attempts")


if __name__ == "__main__":
    text = "Maria moved to Lisbon in 2019; she is 34 and works as a nurse."
    print("prompt-only (parse + validate + retry):")
    print("  result:", extract_person(text))
    print("with response_format json_schema:")
    print("  result:", extract_person(text, use_response_format=True))

"""Minimal agent loop without a framework: model -> tool calls -> results -> model, until done or out of budget."""
import ast
import json
import operator
import os

import requests

BASE_URL = os.environ.get("LOCAL_MODEL_URL") or os.environ.get("BASE_URL", "http://localhost:11434/v1")
MODEL = os.environ.get("LOCAL_MODEL") or os.environ.get("MODEL", "qwen2.5:1.5b")
OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}


def calculator(expression):
    """Deterministic arithmetic in code (no eval): + - * / and parentheses only."""
    def ev(node):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float):
            return node.value
        if isinstance(node, ast.BinOp) and type(node.op) in OPS:
            return OPS[type(node.op)](ev(node.left), ev(node.right))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
            return -ev(node.operand)
        raise ValueError("unsupported expression")
    return ev(ast.parse(expression, mode="eval").body)


# tool registry = allow-list: name -> (function, needs human approval?, tool schema)
REGISTRY = {"calculator": (calculator, False, {"type": "function", "function": {
    "name": "calculator", "description": "Evaluate one arithmetic expression, e.g. '17*23'.",
    "parameters": {"type": "object", "properties": {"expression": {"type": "string"}},
                   "required": ["expression"]}}})}


def execute(name, args, approve=lambda name, args: False):
    if name not in REGISTRY:
        return f"error: unknown tool {name!r}"
    fn, needs_approval, _ = REGISTRY[name]
    if needs_approval and not approve(name, args):  # approval gate: default deny anything risky
        return "error: action denied by human reviewer"
    try:
        return str(fn(**args))
    except Exception as exc:  # errors are data: report them to the model instead of crashing
        return f"error: {exc}"


def run_agent(task, max_steps=5, base_url=BASE_URL, model=MODEL, approve=lambda n, a: False):
    messages = [{"role": "system", "content": "Use the calculator tool for every arithmetic step. "
                                              "You may call tools several times before answering."},
                {"role": "user", "content": task}]
    tools = [schema for _, _, schema in REGISTRY.values()]
    for step in range(1, max_steps + 1):  # step budget: at most max_steps model calls
        resp = requests.post(f"{base_url}/chat/completions", timeout=120, json={
            "model": model, "messages": messages, "tools": tools, "temperature": 0})
        resp.raise_for_status()
        reply = resp.json()["choices"][0]["message"]
        messages.append(reply)  # state = the message list, nothing else
        calls = reply.get("tool_calls") or []
        if not calls:  # stop condition: model gave a final answer
            print(f"step {step}: final -> {reply['content']}")
            return {"answer": reply["content"], "steps": step, "stopped": "final_answer"}
        for call in calls:
            raw = call["function"].get("arguments") or "{}"
            args = raw if isinstance(raw, dict) else json.loads(raw)
            result = execute(call["function"]["name"], args, approve)
            print(f"step {step}: tool  -> {call['function']['name']}({args}) = {result}")
            messages.append({"role": "tool", "tool_call_id": call["id"], "content": result})
    print(f"stopped: max_steps={max_steps} reached without a final answer")
    return {"answer": None, "steps": max_steps, "stopped": "max_steps"}


if __name__ == "__main__":
    task = "Use the calculator to compute 17*23 and (120-20)/4, then report both results."
    print("== budget 5 ==")
    print(run_agent(task, max_steps=5))
    print("== budget 1 ==")
    print(run_agent(task, max_steps=1))
